import json
import re
import datetime
from zoneinfo import ZoneInfo

SOURCE = "automation:AU-05 Book patient's chosen time"
EXPIRE_DAYS = 7
AI_PROMPT = (
    "A clinic offered a patient the numbered appointment times below and asked them to reply with the number "
    "that suits. Read their reply and say which option they chose. Only pick an option if the reply clearly "
    "matches exactly one of them (by number, or by day and time). If they say they don't want to rebook, set "
    "declined to true. If they propose some other time, ask a question, or it's unclear, leave option null."
)
AI_HINT = '{"option": null, "declined": false}'


def read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def delete_file(path):
    try:
        api.files.delete(file=path)
    except Exception:
        pass


def parse_iso(iso):
    try:
        dt = datetime.datetime.fromisoformat(str(iso or "").replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


def utc_iso(dt):
    return dt.astimezone(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def audit(slug, tz, action, target, summary, workq_item_id=""):
    # SK-13 format (healthcare-practice-management-foundation): one JSON line per action, practice-local ts.
    now_local = datetime.datetime.now(tz)
    path = "PracticeManager/AuditLog/" + slug + "-" + now_local.strftime("%Y-%m-%d") + ".jsonl"
    line = {
        "ts": now_local.isoformat(timespec="seconds"), "practice_slug": slug, "actor": "agent",
        "source": SOURCE, "action": action, "target": target, "summary": summary,
    }
    if workq_item_id:
        line["workq_item_id"] = workq_item_id
    try:
        try:
            existing = api.files.read(file=path) or ""
        except Exception:
            existing = ""
        if existing and not existing.endswith("\n"):
            existing += "\n"
        api.files.put(file=path, content=existing + json.dumps(line, sort_keys=True) + "\n")
    except Exception:
        pass


state = params.get("item") or {}
state_path = "PracticeManager/AwaitingReply/" + str(state.get("_file_name") or "")
todo_id = state.get("todo_id") or ""
slug = state.get("slug") or ""
email = str(state.get("email") or "").lower()
patient_name = state.get("patient_name") or "the patient"
offered = state.get("offered_times") or []
offered_display = state.get("offered_display") or []
sent_at = state.get("sent_at") or ""
conversation_id = state.get("conversation_id") or ""
practice = read_json("PracticeManager/Practices/" + slug + ".json", {}) or {}
try:
    tz = ZoneInfo(practice.get("timezone") or "Australia/Sydney")
except Exception:
    tz = datetime.timezone.utc
now = datetime.datetime.now(datetime.timezone.utc)
outcome = "no_reply_yet"


def hand_back(reason):
    # Leave the original approval item open for a person, with everything they need on it.
    api.workq.comment(todo_id=todo_id, body=reason + "\n\nNothing was booked - please follow up by hand in Cliniko.")
    delete_file(state_path)


if not todo_id or not email or not offered or not parse_iso(sent_at):
    delete_file(state_path)
    outcome = "incomplete_record"
else:
    reply = None
    try:
        msgs = api.connectors.invoke(
            server="m365-mail-read", tool="list_emails",
            args={"folder": "inbox", "limit": 50, "receivedAfter": sent_at, "oldestFirst": True},
        )
        msgs = msgs if isinstance(msgs, list) else ((msgs or {}).get("value") or [])
    except Exception:
        msgs = []
    for m in msgs:
        sender = str((((m.get("from") or {}).get("emailAddress")) or {}).get("address") or "").lower()
        if sender != email:
            continue
        if conversation_id and m.get("conversationId") and m.get("conversationId") != conversation_id:
            continue
        reply = m
        break

    if reply is None:
        if now - parse_iso(sent_at) > datetime.timedelta(days=EXPIRE_DAYS):
            hand_back("No reply from " + patient_name + " within " + str(EXPIRE_DAYS) + " days of the reschedule offer.")
            outcome = "expired"
    else:
        reply_text = ""
        try:
            full = api.connectors.invoke(server="m365-mail-read", tool="get_email", args={"id": reply.get("id") or ""}) or {}
            content = ((full.get("body") or {}).get("content")) or ""
            plain = re.sub(r"(?i)<br\s*/?>|</p>|</div>|</tr>", "\n", content)
            plain = re.sub(r"<[^>]+>", " ", plain)
            plain = re.sub(r"[ \t]+", " ", plain)
            # Cut the quoted original (which repeats every offered time) so it can't be read as their choice.
            quote = re.search(r"(?im)^\s*(From:|Sent:|-----Original Message|On .{0,80} wrote:)", plain)
            if quote:
                plain = plain[: quote.start()]
            reply_text = re.sub(r"\s+", " ", plain).strip()
        except Exception:
            reply_text = ""
        if not reply_text:
            reply_text = reply.get("bodyPreview") or ""

        options = [str(i + 1) + ". " + d for i, d in enumerate(offered_display)]
        try:
            parsed = api.ai.extract(prompt=AI_PROMPT, input=json.dumps({"options": options, "reply": reply_text}), schema_hint=AI_HINT)
        except Exception:
            parsed = {}
        parsed = parsed if isinstance(parsed, dict) else {}
        option = parsed.get("option")
        try:
            option = int(option) if option is not None else None
        except Exception:
            option = None
        reply_note = "**Their reply:** " + (reply_text[:1000] or "(empty)") + "\n**Times offered:** " + ", ".join(offered_display)

        if parsed.get("declined") is True and option is None:
            api.workq.comment(todo_id=todo_id, body=patient_name + " replied that they don't want to rebook. Nothing was booked.\n\n" + reply_note)
            api.workq.complete(todo_id=todo_id)
            delete_file(state_path)
            audit(slug, tz, "read", {"kind": "email", "id": reply.get("id") or ""}, patient_name + " declined the reschedule offer", todo_id)
            outcome = "declined"
        elif option is None or not (1 <= option <= len(offered)):
            hand_back("Couldn't tell which time " + patient_name + " picked.\n\n" + reply_note)
            outcome = "needs_human"
        else:
            chosen_iso = offered[option - 1]
            chosen_display = offered_display[option - 1] if option - 1 < len(offered_display) else chosen_iso
            chosen_dt = parse_iso(chosen_iso)

            # Re-check the time is still free right before booking - it may have gone since the offer was sent.
            still_free = False
            if chosen_dt and chosen_dt > now:
                local_day = chosen_dt.astimezone(tz).date()
                try:
                    avail = api.connectors.invoke(
                        server="cliniko-scheduling", tool="get_available_times",
                        args={
                            "business_id": state.get("business_id"), "practitioner_id": state.get("practitioner_id"),
                            "appointment_type_id": state.get("appointment_type_id"),
                            "from_time": local_day.isoformat(),
                            "to_time": (local_day + datetime.timedelta(days=1)).isoformat(),
                        },
                    )
                    for s in (avail or {}).get("available_times") or []:
                        t = parse_iso(s.get("appointment_start") if isinstance(s, dict) else s)
                        if t and t == chosen_dt:
                            still_free = True
                            break
                except Exception:
                    still_free = False

            if not still_free:
                hand_back(patient_name + " picked " + chosen_display + ", but that time is no longer free in Cliniko.\n\n" + reply_note)
                outcome = "slot_taken"
            else:
                appointment = {
                    "appointment_type_id": state.get("appointment_type_id"),
                    "business_id": state.get("business_id"),
                    "practitioner_id": state.get("practitioner_id"),
                    "patient_id": state.get("patient_id"),
                    "starts_at": utc_iso(chosen_dt),
                }
                old_start = parse_iso(state.get("cancelled_starts_at"))
                old_end = parse_iso(state.get("cancelled_ends_at"))
                if old_start and old_end and old_end > old_start:
                    appointment["ends_at"] = utc_iso(chosen_dt + (old_end - old_start))
                try:
                    created = api.connectors.invoke(
                        server="cliniko-scheduling", tool="create_individual_appointment",
                        args={"appointment": appointment},
                    ) or {}
                    book_error = ""
                except Exception as exc:
                    created = {}
                    book_error = str(exc)

                if book_error:
                    hand_back(patient_name + " picked " + chosen_display + ", but Cliniko rejected the booking: " + book_error + "\n\n" + reply_note)
                    outcome = "booking_failed"
                else:
                    new_id = str(created.get("id") or "")
                    audit(slug, tz, "edited", {"kind": "appointment", "id": new_id},
                          "Booked " + patient_name + " at the time they picked from the approved reschedule offer", todo_id)
                    confirmed = True
                    try:
                        api.connectors.invoke(
                            server="m365-mail-send", tool="reply_to_email",
                            args={
                                "id": reply.get("id") or "",
                                "comment": "Hi " + patient_name + ",<br><br>You're booked in for " + chosen_display
                                + ". See you then!<br><br>Kind regards",
                            },
                        )
                        audit(slug, tz, "sent", {"kind": "email", "id": reply.get("id") or ""},
                              "Confirmed the new booking to " + patient_name, todo_id)
                    except Exception:
                        confirmed = False
                    api.workq.comment(
                        todo_id=todo_id,
                        body=(
                            "Booked " + patient_name + " for " + chosen_display + " (Cliniko appointment " + (new_id or "id not returned") + ")"
                            + (" and confirmed it to them by email." if confirmed else ". The confirmation email failed to send - let them know yourself.")
                            + "\n\n" + reply_note
                        ),
                    )
                    if confirmed:
                        api.workq.complete(todo_id=todo_id)
                    delete_file(state_path)
                    outcome = "booked"
